def consume_quota(bucket, identity):
    remaining = bucket.decrement(identity)
    if remaining < 0:
        raise RuntimeError('too many requests')
    return remaining

files.network/retry.py:
def transient_call(operation, attempts):
    for number in range(attempts):
        try:
            return operation()
        except TimeoutError:
            if number + 1 == attempts:
                raise

